<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $routes = collect(\Route::getRoutes())->map->getName()->filter()->toArray(); $menuItems = \App\Models\MenuItem::whereNotNull("route_name")->get(); $duplicates = []; $seen = []; $missing = []; foreach($menuItems as $item) { if(!in_array($item->route_name, $routes)) { $missing[] = $item->id; } elseif(in_array($item->route_name, $seen)) { $duplicates[] = $item->id; } else { $seen[] = $item->route_name; } } print_r(["missing" => $missing, "duplicates" => $duplicates]); \App\Models\MenuItem::destroy($missing); \App\Models\MenuItem::destroy($duplicates);
